UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE('Base da tela de Premissas em 1 ida (CICLOS nao-fechados + CONTAS como JSON). Sem params.', DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',ID,''NOME'',NOME,''ANO'',ANO,''STATUS'',STATUS,''ULTIMO_MES_REALIZADO'',ULTIMO_MES_REALIZADO,''VERSAO_ATUAL'',VERSAO_ATUAL,''VERSAO_CONTROLE'',VERSAO_CONTROLE,''VERSAO_ORIGEM_ID'',VERSAO_ORIGEM_ID,''CRIADO_EM'',CRIADO_EM,''CRIADO_POR'',CRIADO_POR)) FROM CICLO WHERE STATUS != ''FECHADO''), JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',ID,''CODIGO'',CODIGO,''NOME'',NOME)) FROM CONTA_CONTABIL), JSON_ARRAY()) AS CONTAS', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'hotPremissasBase';
